using System; using System.Collections.Generic; using System.Linq; using AshkanPharmacy.Models;
namespace AshkanPharmacy.Core { public static class FefoService { public static List<MedicineBatch> Allocate(IEnumerable<MedicineBatch> batches,int requested) { if(requested<=0) throw new ArgumentOutOfRangeException("requested"); var result=new List<MedicineBatch>(); var left=requested; foreach(var b in batches.Where(x=>x.Quantity>0 && x.ExpiryDate.Date>=DateTime.Today).OrderBy(x=>x.ExpiryDate)){ if(left==0) break; var take=Math.Min(left,b.Quantity); result.Add(new MedicineBatch{Id=b.Id,MedicineId=b.MedicineId,BatchNo=b.BatchNo,ExpiryDate=b.ExpiryDate,Quantity=take,PurchasePrice=b.PurchasePrice}); left-=take;} if(left>0) throw new InvalidOperationException("Insufficient non-expired batch stock."); return result; } } }